package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Fraction_compareTo_TriageGen0Test {

    @Test
    public void testCompareTo_Less() {
        Fraction f1 = new Fraction(1, 3); // 0.333...
        Fraction f2 = new Fraction(1, 2); // 0.5
        // nOd < dOn should return -1
        assertEquals(-1, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_Greater() {
        Fraction f1 = new Fraction(2, 3); // 0.666...
        Fraction f2 = new Fraction(1, 3); // 0.333...
        // nOd > dOn should return +1
        assertEquals(1, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_Equal() {
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(2, 4);
        // nOd == dOn should return 0
        assertEquals(0, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_NegativeValues() {
        Fraction f1 = new Fraction(-1, 2); // -0.5
        Fraction f2 = new Fraction(1, 2);  // 0.5
        assertEquals(-1, f1.compareTo(f2));

        Fraction f3 = new Fraction(-1, 4); // -0.25
        Fraction f4 = new Fraction(-1, 2); // -0.5
        assertEquals(1, f3.compareTo(f4));
    }

    @Test
    public void testCompareTo_Zero() {
        Fraction zero = new Fraction(0, 1);
        Fraction positive = new Fraction(1, 1);
        Fraction negative = new Fraction(-1, 1);

        assertEquals(-1, zero.compareTo(positive));
        assertEquals(1, zero.compareTo(negative));
        assertEquals(0, zero.compareTo(zero));
    }

    @Test
    public void testCompareTo_LargeValues() {
        Fraction f1 = new Fraction(1000000, 1);
        Fraction f2 = new Fraction(2000000, 1);
        assertEquals(-1, f1.compareTo(f2));

        Fraction f3 = new Fraction(2000000, 1);
        assertEquals(1, f3.compareTo(f1));
    }
}
